import{_ as o,l as r,o as e,c as l,v as n,p as s,x as i,d as E,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"原罪与货币错配","description":"","frontmatter":{"title":"原罪与货币错配","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/original-sin.md","filePath":"econ/original-sin.md","lastUpdated":1789023840000}'),c={name:"econ/original-sin.md"};function h(A,a,u,_,B,m){const t=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=n('<h1 id="原罪与货币错配" tabindex="-1">原罪与货币错配 <a class="header-anchor" href="#原罪与货币错配" aria-label="Permalink to &quot;原罪与货币错配&quot;">​</a></h1><div class="epigraph"><p>若一国不能以本币向外国人借长期债，贬值就不再只是支出转换，而是把外债的本币负担一起抬起来。</p><footer>—— Eichengreen and Hausmann, Exchange Rates and Financial Fragility, Jackson Hole 1999</footer></div><p><a href="/econ/sudden-stop">上一课</a>让资本流入骤停，浮动角上 \\(E\\) 可以贬来调 \\(CA\\)。本课的缺口是负债的币种：Eichengreen 与 Hausmann 的原罪——新兴市场往往不能用本币借外债，于是突然停止遇上货币错配。宏观主干的开放课序到此结束；下一课起问金融中介为什么仍然存在——无论三角选哪一边，不可交易的初级债权还在。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>蒙代尔与多恩布什把贬值写成净出口改善。若银行、企业或政府的负债是美元、资产是本币现金流，则 \\(E\\) 贬值使净值下降，信贷收缩，\\(I\\) 与 \\(Y\\) 可以掉得比支出转换的收益更大。原罪是市场结构事实：外国人不愿持有该国本币长期债，国内也不深。缺口不是再讲三难，而是：为什么「让 \\(E\\) 动」在错配下不再是免费的稳定器。CIP 对冲在原则上能把外币债换成合成本币债，但市场深度、期限与主权风险会挡住；报价层见 <code>/quant/irp</code>，本课不编基差。</p><p>上一课的突然停止是流量断裂。本课把存量币种叠上去：同一 \\(\\Delta e\\)，无错配是转换，有原罪是净值税。开放宏观主干到此结束；中介课序从 Gurley–Shaw 另起，不再重写三角。</p><p><span class="marginnote">原罪不是道德标签。它是：国际资产负债表上，负债的币种与不可贸易收入的币种对不上。发达经济体较多以本币借外债，贬值的净值通道弱得多。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把开放经济的主体写成双重账户：流量 \\(CA\\)，存量是外币债。突然停止迫使 \\(CA\\) 改善，若走贬值，\\(q\\) 转换出口，同时外币债的本币值上升。净值下降 → 抵押与信贷配给收紧（下一课程的 Stiglitz–Weiss 会解释利率为何不能单独出清）→ 吸收更猛地砍。钉住可以暂时避免重估，但停止时守 \\(E\\) 要加息或耗储备，同样打净值——三角没有第四个顶点。</p>',9)),(e(),s(p,null,{default:i(()=>[d(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SS%5B%22%E7%AA%81%E7%84%B6%E5%81%9C%E6%AD%A2%22%5D%20--%3E%20E%5B%22E%20%E8%B4%AC%E5%80%BC%22%5D%0A%20%20OSIN%5B%22%E5%8E%9F%E7%BD%AA%EF%BC%9A%E5%A4%96%E5%B8%81%E5%80%BA%22%5D%20--%3E%20NW%5B%22%E5%87%80%E5%80%BC%E4%B8%8B%E9%99%8D%22%5D%0A%20%20E%20--%3E%20NX%5B%22%E6%94%AF%E5%87%BA%E8%BD%AC%E6%8D%A2%EF%BC%9ANX%20%E6%94%B9%E5%96%84%22%5D%0A%20%20E%20--%3E%20NW%0A%20%20NW%20--%3E%20CRED%5B%22%E4%BF%A1%E8%B4%B7%E6%94%B6%E7%BC%A9%22%5D%0A%20%20NX%20--%3E%20Y%5B%22Y%20%E7%9A%84%E5%87%80%E6%95%88%E5%BA%94%E4%B8%8D%E5%AE%9A%22%5D%0A%20%20CRED%20--%3E%20Y%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<p>Eichengreen–Hausmann 把原罪与金融脆弱性写在同一篇 Jackson Hole 论文里：汇率制度选择被资产负债表绑住。后来的「原罪」文献区分国际原罪（对外国人发本币债）与国内原罪（本币长期市场浅）。本课取国际原罪为最小定义。</p><h3 id="对冲不是自动取消原罪" tabindex="-1">对冲不是自动取消原罪 <a class="header-anchor" href="#对冲不是自动取消原罪" aria-label="Permalink to &quot;对冲不是自动取消原罪&quot;">​</a></h3><p>企业可以买远期。CIP 成立时，抛补成本接近利差，合成本币债的成本已经写在价格里——原罪变成「按这个价格借不到足够期限」。CIP 偏离时，对冲本身变贵或额度没了，停止发生的同一周对冲市场先干。不要用某个基点去讲故事；机制是额度与币种，不是屏幕上的小数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>贬值的宏观教科书收益是 \\(q\\) 转换。错配把同一 \\(\\Delta e\\) 写成存量税：外币债权人的本币索取上升，本币债务人的股本被擦掉。银行资本一薄，流动性转换下一课程会更脆。长期中性仍在：名义锚最终要选，原罪不否定 PPP 的慢趋势；它改变的是过渡路径上 \\(Y\\) 对 \\(\\Delta e\\) 的符号。铸币税与本币债深度相关：能以本币借，才能把通胀税与债务稀释写在同一计价单位里；原罪国家的稀释打的是净值，不是慢慢的铸币税。</p><p>时间不一致：宣布钉住以保护错配资产负债表，停止时又想贬，公众与债权人把再优化算进利差。承诺要么是更深的本币债市场（慢），要么是三角上事先选边。Dornbusch 超调在错配下可以变成「贬值越深、净值越差、信贷越紧」，符号与无错配的支出转换相反——同一 \\(\\Delta e\\)，两套资产负债表。FTPL 的本币债稀释在原罪下不容易用，因为债不在本币上。</p><p><span class="marginnote">货币错配可以发生在没有「新兴市场」标签的表上：企业借外汇、收入在国内。原罪强调的是系统性：整个国家在国际市场上借不到本币。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计某国的外币债份额，不把原罪写成不可改变的命运——本币市场可以长出来。不要把限价簿当外债微观结构。MM 的资本结构无关性在开放错配下破了：币种是一种切片，家庭很难自制主权币种。下一课程从 Gurley–Shaw 接过转换功能，不再重写三角。对冲的市场内容仍在 <code>/quant/irp</code>，本课不编基差。</p><p>国内原罪（本币长期市场浅）与国际原罪可以分开；本课取国际原罪为最小定义。主权以本币借、银行以外币借，错配可以藏在银行表上——宏观加总仍是同一币种问题。</p><p>后课默认：不能用本币借外债时，贬值有净值通道。下一课进入货币银行：中介为何要把初级债权改写成存款。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>原罪：难以用本币向外国人借长期债。</li><li>贬值同时做支出转换与外币负债重估，净效应可以是收缩。</li><li>突然停止因此从流量危机变成资产负债表危机。</li><li>对冲受期限与额度限制；实证基差不在本栏编造。</li><li>本币债市场可以长出来，原罪不是命运标签。</li><li>出处：Eichengreen and Hausmann, Jackson Hole 1999。</li></ul>',13))])}const f=o(c,[["render",h]]);export{C as __pageData,f as default};
